27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ and 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
61	    private Set<Pet> pets;
62	
63	    public String getAddress() {
64	        return this.address;
65	    }
66	
67	    public void setAddress(String address) {
68	        this.address = address;
69	    }
70	
71	    public String getCity() {
72	        return this.city;
73	    }
74	
75	    public void setCity(String city) {
76	        this.city = city;
77	    }
78	
79	    public String getTelephone() {
80	        return this.telephone;
81	    }
82	
83	    public void setTelephone(String telephone) {
84	        this.telephone = telephone;
85	    }
86	
87	    public String getEmail() {
88	        return this.email;
89	    }
90	
91	    /**
92	     * Stores the email in its canonical lower-cased form so it is always persisted and
93	     * returned lower-cased, regardless of the casing supplied by the client.
94	     */
95	    public void setEmail(String email) {
96	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
97	    }
98	
99	    public LocalDate getRegistrationDate() {
100	        return this.registrationDate;
101	    }
102	
103	    public void setRegistrationDate(LocalDate registrationDate) {
104	        this.registrationDate = registrationDate;
105	    }
106	
107	    public String getCustomerCode() {
108	        return this.customerCode;
109	    }
110	
111	    public void setCustomerCode(String customerCode) {
112	        this.customerCode = customerCode;
113	    }
114	
115	    /**
116	     * On first persist, default the registration date to the server's current date
117	     * when the client did not supply one, leaving any supplied date untouched.
118	     */
119	    @PrePersist
120	    private void defaultRegistrationDate() {
121	        if (this.registrationDate == null) {
122	            this.registrationDate = LocalDate.now();
123	        }
124	    }
125	
126	    protected Set<Pet> getPetsInternal() {
127	        if (this.pets == null) {
128	            this.pets = new HashSet<>();
129	        }
130	        return this.pets;
131	    }
132	
133	    protected void setPetsInternal(Set<Pet> pets) {
134	        this.pets = pets;
135	    }
136	
137	    public List<Pet> getPets() {
138	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
139	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
140	        return Collections.unmodifiableList(sortedPets);
141	    }
142	
143	    public void setPets(List<Pet> pets) {
144	        this.pets = new HashSet<>(pets);
145	    }
146	
147	    public void addPet(Pet pet) {
148	        getPetsInternal().add(pet);
149	        pet.setOwner(this);
150	    }
151	
152	    /**
153	     * Return the Pet with the given name, or null if none found for this Owner.
154	     *
155	     * @param name to test
156	     * @return true if pet name is already in use
157	     */
158	    public Pet getPet(String name) {
159	        return getPet(name, false);
160	    }
161	
162	    /**
163	     * Return the Pet with the given name, or null if none found for this Owner.
164	     *
165	     * @param name to test
166	     * @return true if pet name is already in use
167	     */
168	    public Pet getPet(String name, boolean ignoreNew) {
169	        name = name.toLowerCase();
170	        for (Pet pet : getPetsInternal()) {
171	            if (!ignoreNew || !pet.isNew()) {
172	                String compName = pet.getName();
173	                compName = compName.toLowerCase();
174	                if (compName.equals(name)) {
175	                    return pet;
176	                }
177	            }
178	        }
179	        return null;
180	    }
181	
182	    public Pet getPet(Integer petId) {
183	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
184	    }
185	
186	    @Override
187	    public String toString() {
188	        return new ToStringCreator(this)
189	
190	            .append("id", this.getId())
191	            .append("new", this.isNew())
192	            .append("lastName", this.getLastName())
193	            .append("firstName", this.getFirstName())
194	            .append("address", this.address)
195	            .append("city", this.city)
196	            .append("telephone", this.telephone)
197	            .append("email", this.email)
198	            .toString();
199	    }
200	}
